"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0876-09-24:0":{"b": ["Ibn al-Saqiyya dies; his son Muhammad takes the throne (263, 876-77).", "89f473df"], "d": ["Ibn al-Saqiyya dies; his son Muhammad takes the throne (263, 876-77).", "89f473df"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0883-07-11:0":{"b": ["Muhammad dies; his uncle Elyesa' II succeeds to the emirate (270, 883).", "1a21eeb6"], "d": ["Muhammad dies; his uncle Elyesa' II succeeds to the emirate (270, 883).", "1a21eeb6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0903-07-01:0":{"b": ["The Qarmatians besiege Damascus; the leader Sahib al-Naqa Yahya is killed during the siege", "9b876cc8"], "d": ["Yahya, known as Sahib al-Naqa, one of the sons of Zikrawayh ibn Mihrawayh, was killed during the siege of Damascus in Sha'ban 290 (July 903); his brother Sahib al-Shama took his place and, after an unsuccessful attack on Aleppo, seized Hama, Homs, Ma'arrat al-Nu'man and Baalbek.", "9980a87c"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0906-01-01:0":{"b": ["The Qarmatian da'i Abu Ghanim plunders Busra, Tiberias and Hit, then enters Kufa; he is soon expelled", "7b175ddd"], "d": ["Abu Ghanim Abdullah ibn Sa'id and his men, sent by Zikrawayh to revive Qarmatism among the Banu Kalb, plundered settlements such as Busra, Adhri'at, Tiberias and Hit and attacked Damascus; failing to achieve success, they entered Kufa but were soon expelled from the city (293/906).", "e62c81d1"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0911-01-01:0":{"b": ["The Turfan Uighur state becomes independent", "d48689ad"], "d": ["The Turfan Uighur state becomes independent", "d48689ad"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0913-01-01:0":{"b": ["Abu Sa'id al-Jannabi is killed in an assassination arranged by Ubayd Allah al-Mahdi (301); his sons continue the state.", "dd507fc0"], "d": ["Abu Sa'id al-Jannabi is killed in an assassination arranged by Ubayd Allah al-Mahdi (301); his sons continue the state.", "dd507fc0"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0931-01-24:0":{"b": ["Abu Tahir hands the administration of Bahrain to a Persian whom he presented as the mahdi; the new mahdi is killed eighty days later", "1816f4a5"], "d": ["Abu Tahir al-Jannabi, who had taken Oman (318/930), the following year handed the administration of Bahrain to a Persian whom he had brought from Isfahan and presented to the people as the mahdi. When the Persian presented himself as a descendant of the ancient Persian Khosraus and a reformer of the Persian religion and put forward ideas against the Arabs, he was killed by Abu Tahir eighty days after being installed; this caused great bewilderment and dispersal among the Bahrain Qarmatians.", "919b72ac"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0935-01-01:0":{"b": ["Mardawij is killed in Isfahan by his Turkish soldiers; his brother Washmgir succeeds him (323/935).", "11355262"], "d": ["Mardawij is killed in Isfahan by his Turkish soldiers; his brother Washmgir succeeds him (323/935).", "11355262"]},
